	-- Compartir (fase 3)
	RITUAL_COACH_SHARE_BTN = "Compartir consejos de challenges con el grupo",
	RITUAL_SHARE_CHALLENGES_HEADER = "Challenges de ritual por Spoils:",
	RITUAL_SHARE_XLOC_HEADER_FMT = "%s compartió consejos de challenges de ritual:",
	RITUAL_SHARE_CONFIRM_FMT = "¿Publicar %d líneas de consejos de challenges en tu grupo?",
	RITUAL_SHARE_SENT_FMT = "%d línea(s) compartida(s) en %s.",
	RITUAL_SHARE_SENT_TEST_FMT = "%d línea(s) compartida(s) (modo de prueba).",
	RITUAL_SHARE_NO_GROUP = "Únete a un grupo o banda para compartir estos consejos (o activa el modo de prueba de compartir).",
	RITUAL_SHARE_COMBAT = "No se puede compartir en combate.",
	RITUAL_SHARE_COOLDOWN = "Compartir está en enfriamiento — inténtalo de nuevo en un momento.",
	RITUAL_SHARE_BUSY = "Ya hay un envío en curso.",
	RITUAL_SHARE_FAILED = "No se pudieron generar los consejos de challenges.",

	-- Pista semanal (por qué la semanal de Ritual sigue pendiente)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Bloqueado: %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Bloqueado — desbloquea los Ritual Sites con la cadena de misiones de introducción en Lunargenta.",
	RITUAL_WEEKLY_HINT_PICKUP = "Aún sin recoger — coge la semanal de esta semana en el centro del Bazar en Lunargenta.",
	RITUAL_WEEKLY_HINT_INTRO = "Este personaje aún no ha terminado la cadena de misiones de introducción — empieza \"Ranger Captain's Summons\" con Ranger Captain Lilatha en Lunargenta (el paso Void Strike se hace en la zona de asalto activa).",
	RITUAL_INTRO_STEP_FMT = "Cadena de introducción en este personaje — paso %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(ya está en tu registro de misiones)",
	RITUAL_INTRO_STEP_SUMMONS = "empieza \"Ranger Captain's Summons\" con Ranger Captain Lilatha, en el campamento sobre el Bazar.",
	RITUAL_INTRO_STEP_ALLIES = "haz \"Outfitting and Allies\" — conoce a los aliados en el campamento de Lilatha.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — este paso ocurre en la zona de asalto activa (ver Void Assaults abajo).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — investiga los informes de los sitios rituales y luego interrumpe un sitio ritual.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — preséntate ante Lady Darkglen en el campamento.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "Está en tu registro de misiones — termínala y entrégala.",

	-- Intro / cómo funciona ----------------------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Elige tu tier en el Curious Obelisk; cada tier debe completarse para desbloquear el siguiente.|n• El obelisco dice qué pide cada tier: el Tier 3 requiere 1 challenge activo, el Tier 4 requiere 2, el Tier 5 requiere 4, el Tier 6 requiere 6.|n• Los tiers más altos dan más Spoils y renombre. Nivel de objeto recomendado, leído del propio obelisco el 20 de agosto: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Pasa el ratón por un tier en el desplegable para comprobarlo tú mismo — estos números cambian entre temporadas.",
	RITUAL_TIP_INTRO_SCORING = "• Los Spoils son tu puntuación; el Ritual Chest del final escala con ellos.|n• Muertes: las 2 primeras son gratis, después cada muerte resta un 5% de Spoils, hasta un máximo de -50%.|n• Limpiar con cuidado gana a los pulls rápidos — morir cuesta recompensas directamente.",
	RITUAL_TIP_INTRO_WEEKLY = "• Cada semana, el tier necesario para DESBLOQUEAR un challenge baja en uno, así que con el tiempo todos lo desbloquean todo.|n• No puedes desbloquear los 8 challenges en una sola semana.|n• Cuenta para la fila de Mundo del Great Vault.|n• Potenciadores de renombre: Ritual Tablet (primer sitio de la semana), Ritual Tablet Fragment (segundo sitio) y Ritual Site Reports (según tus Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• En combate aparecen Regeneration Orbs que curan el 15% de tu vida (renombre 1).|n• Orb Potency (renombre 4) aumenta esa curación.|n• Apóyate en los orbes en lugar de quemar cooldowns en curarte.",

	-- Daggerspine Point (Eversong Woods) ----------------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, en la costa oeste cerca de Goldenmist Village.|n• Enemigos: nagas.|n• Activo una semana cada vez; el obelisco muestra un icono morado en el mapa.|n• Entra por el Curious Obelisk y elige allí tu tier + challenges.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Un escenario corto instanciado: completa objetivos y oleadas de enemigos, luego un jefe final, y al final saquea el Ritual Chest.|n• Escenario visto en el obelisco: \"A Strike From the Sea\" — la líder naga Selen'vjar (muerte del jefe final por confirmar).|n• Un sitio puede tener más de un diseño de escenario — por confirmar en el juego.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (desbloquea el challenge Tainted Corpses): /way 66.09 62.58.|n• Dark Obelisks (misión Malevolent Boons — investiga 5 de 9): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• Hay pequeños tesoros y Regeneration Orbs repartidos por el sitio.",

	-- Broken Throne (Zul'Aman) ------------------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, en el sur de la zona.|n• Enemigos: cultistas de Twilight's Blade.|n• Activo una semana cada vez; el obelisco muestra un icono morado en el mapa.|n• Entra por el Curious Obelisk y elige allí tu tier + challenges.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Un escenario corto instanciado: completa objetivos y oleadas de enemigos, luego un jefe final, y al final saquea el Ritual Chest.|n• Escenario visto en el obelisco: \"A Corrupted Path\" — Faithbreaker Ger'lok lo corrompe todo con el Vacío y es el jefe final.|n• LETAL en los jefes finales (incluido el Corrupted Amani Dragonhawk): reflejos del Vacío (Dissonant Reflections) aparecen sin parar y lanzan Dissonant Realities — una explosión enorme sobre todo en 100 metros. No puedes alejarte: INTERRUMPE el lanzamiento y el reflejo desaparece al instante. Guarda tu interrupción justo para esto.|n• Corrupted Amani Dragonhawk: una Binding Nebula te ATRAPA — no puedes salir hasta que MATAS la propia nebulosa, así que revientala en cuanto te atrape. Los jugadores atrapados mueren por Volatile Plumage (la erupción de plumas golpea por cientos de miles); nunca te pongas frente al Shadowflame Breath.|n• Un sitio puede tener más de un diseño de escenario — por confirmar en el juego.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (desbloquea el challenge Tainted Corpses): /way 47.91 36.52.|n• Dark Obelisks (misión Malevolent Boons — investiga 5 de 6): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54.|n• Destruir los Dark Obelisks elimina las mejoras que potencian a los enemigos del sitio — limpiarlos hace que los jefes sean notablemente más fáciles (déjalos en pie solo si vas a por el logro sin obeliscos).|n• Hay pequeños tesoros y Regeneration Orbs repartidos por el sitio.",
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291610} deja pequeños CHARCOS ROJOS. Ponte en uno para soakearlo: solo recibes un golpe pequeño. Un charco en el que nadie se pone estalla con un daño enorme de Shadowflame y puede matar a todo el grupo. Basta un jugador por charco.|n• {SPELL:1284125}: se forma una nebulosa bajo un jugador al azar. Hace daño cada segundo y te ralentiza un 40 %. No puedes salir mientras viva, así que mata la nebulosa para liberarte.|n• {SPELL:1284081}: aparecen sin parar espejos del Vacío en el centro y lanzan Dissonant Realities, un golpe enorme a todos en 100 metros. No puedes huir de él. Interrumpe el lanzamiento y el espejo desaparece. Guarda tu interrupción para esto.|n• Ponte DETRÁS del dracohalcón. Su Shadowflame Breath frontal es letal.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Charcos rojos: Ponte en un charco rojo para que no explote sobre todos.|nEspejo: Interrumpe el hechizo del espejo del centro, o golpea fuerte a todos.|nNebulosa: Si una nube oscura te atrapa, mata la nube para salir.",
	RITUAL_BOSS_GERLOK_STEPS = "• Invoca esbirros que lo vuelven (casi) inmune al daño. Quema cada add en cuanto aparezca. Los adds cargan con un canal de fuego que casi te mata de un golpe, así que sal de él.|n• {SPELL:1273031} es EL lanzamiento que hay que interrumpir: un golpe fuerte a todos los que estén cerca. No todos sus lanzamientos se pueden cortar, así que guarda tu interrupción para este.|n• {SPELL:1279186} lo lanza sin parar. Rompe la línea de visión detrás de los pilares.|n• Mantenlo EN su plataforma. Bajarlo o sacarlo de ella reinicia el combate (Rob, en el juego). El espacio es estrecho, pero no busques sitio más abajo.|n• Challenge Embers: cada Ember que sigue ardiendo lo hace mucho más fuerte. Un jugador en Wowhead vio cerca de un 60 % más de vida y daño con los cuatro activos. Mata a los enemigos marcados alrededor de cada Ember antes del jefe para apagarlo.",
	RITUAL_BOSS_GERLOK_QUICK = "Adds: Mata a sus ayudantes enseguida, porque mientras viven casi no recibe daño.|nInterrumpir: Guarda tu interrupción para Shadowbolt Volley, su golpe fuerte a todos.|nPilares: Escóndete detrás de un pilar para que su Shadow Blast no te alcance.",
	RAID_BOSS_ROTMIRE_STEPS = "• Un jefe y un ciclo que se repite hasta que muere. Ansia de sangre al pull. Cada {SPELL:1221787} añade una acumulación de Rotting Pustules que se queda, así que el daño al raid no para de subir: cuanto más dura el combate, más difícil.|n• {SPELL:1221622}: unos círculos en el suelo muestran dónde salen los adds. Sal de ellos, o te lanzan lejos y te hacen mucho daño. Cada add (Shroomling) persigue a un jugador: llévalo a un solo montón apretado cerca del jefe, para que el raid los mate a todos juntos.|n• Mata todos los adds antes de que su barra de energía se llene. Con 100 de energía lanza {SPELL:1221637}: un golpe a todos, un empujón y un DoT de 16 segundos. Un add que siga vivo entonces recibe Fungal Frenzy: vida completa, y ya no se puede aturdir ni interrumpir.|n• Después de {SPELL:1221637}, cada cadáver de add se convierte en un Bursting Shroom. Mátalos todos en unos 16 segundos: cada uno que quede explota sobre todo el raid, y más de una explosión suele ser wipe. Por eso los adds mueren en un solo montón.|n• {SPELL:1222088} ralentiza a unos cuantos jugadores y les hace daño. Camina al borde de la sala antes de que termine: deja una zona ({SPELL:1222129}) que se queda. Mantén libres el centro y el montón de adds, y sal de cualquier zona.|n• En Heroico y Mítico: también aparece un add Sporecap que no se mueve. Interrumpe su Poison Burst todas las veces, o todo el raid acumula un DoT. Lleva los demás adds hasta él y mátalos ahí.|n• En Mítico: también vienen Funglings. Un cadáver de Shroomling a menos de 10 metros de un cadáver de Fungling crea un Bursting Doom Shroom, y eso es wipe del raid. Mata los dos tipos en dos sitios separados.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Mata todos los adds del montón antes de que su barra se llene, y luego mata las setas al instante.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "El daño sube en cada ciclo, así que guarda cooldowns para el golpe fuerte cuando su barra se llena.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Cambia con el otro tanque después de cada golpe fuerte, y deja al jefe junto al montón de adds.",
	RAID_BOSS_ROTMIRE_QUICK = "Adds: Junta los pequeños adds de seta en un solo montón y mátalos antes de que su barra de energía se llene.|nSetas: Cuando su barra se llena, los adds muertos se vuelven setas, así que mátalas rápido antes de que exploten.|nEnredaderas: Si unas enredaderas te frenan, ve al borde de la sala para que el charco que dejan no moleste a nadie.",
	RAID_BOSS_ROTMIRE_TANK = "• Cambia con el otro tanque después de cada {SPELL:1221781}: te lanza por los aires y te hace recibir más daño físico durante 14 segundos (35 % en Normal, 75 % en Heroico y Mítico). Usa un defensivo para el golpe.|n• Mantén al jefe junto al montón de adds, para que el raid le pegue mientras mata a los adds. En Heroico y Mítico: llévalo al Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• El daño al raid sube durante todo el combate: cada {SPELL:1221787} añade una acumulación de Rotting Pustules, así que cada ciclo es más duro que el anterior.|n• Planifica cooldowns de raid para {SPELL:1221637} (un golpe más un DoT de 16 segundos a todos) y para cualquier Bursting Shroom que explote.|n• El tanque al que golpea {SPELL:1221781} recibe mucho más daño físico durante 14 segundos.",
	RAID_BOSS_ROTMIRE_DPS = "• Haz cleave a los adds en su montón, y que todos estén muertos antes de {SPELL:1221637}. Luego cambia a los Bursting Shrooms al instante.|n• En Heroico y Mítico: interrumpe el Poison Burst del Sporecap todas las veces.|n• En Mítico: los Shroomlings y los Funglings mueren en dos sitios separados, a 10 metros o más uno del otro.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100La entrada está BAJO EL AGUA|r — una cueva sumergida, así que tu barra de aliento corre antes del combate. Hay burbujas de aire en la entrada para rellenarla.|n• Un jefe, un ciclo que se repite hasta que muere. Cuenta para la fila de Raid de tu Great Vault.|n• |cffffd100Los múrlocs son el combate.|r {SPELL:1257717} pone una gran burbuja en el centro y los múrlocs corren hacia ella. Mátalos o ralentízalos ANTES de que lleguen — cada uno que entra se vuelve un Berserker que golpea a todo el grupo cada 3 segundos. Lleva al jefe al grupo más grande; los de distancia se encargan de los sueltos.|n• Remolinos rodean la sala con un solo hueco entre ellos — agrupaos en ese hueco.|n• Cuando un remolino llega a la burbuja, estalla: daño a todos y un empujón. Colócate para no salir despedido al agua — hay tiburones.|n• {SPELL:1313393}: si te toca, dejas orbes de escarcha donde pisas. Déjalos juntos, lejos de la burbuja y de los caminos. En Normal no los toques (daño acumulado y hielo resbaladizo); en Heroico y Mítico hay que recogerlos o estallan sobre todo el grupo.|n• {SPELL:1260837} son cuatro segundos de daño a todos — un cooldown de sanación. En Heroico y Mítico cada uno la hace pegar más fuerte: el enrage lento.|n• A los 10 minutos llega el enrage final: se acabó el pull.|n• Ansia de sangre al pull.|n• Según las guías en vivo y el módulo actual de DBM, aún no probado por nosotros — cuéntanos lo que viste.",
	RAID_BOSS_NYMRISSA_TANK = "• Normal y Heroico: {SPELL:1282937} son varios segundos de golpes fuertes sobre ti — usa un defensivo. No hay nada que apuntar.|n• Mítico: {SPELL:1268562} es una línea que te empuja y se acumula; apúntala lejos del grupo (a través de las placas de hielo, las borra) y cambia con el otro tanque en las acumulaciones.|n• Mantenla junto al grupo de múrlocs más grande, nunca encima de la burbuja.",
	RAID_BOSS_NYMRISSA_HEALER = "• Planifica cooldowns para {SPELL:1260837} (cuatro segundos sobre todos) y para el estallido de la burbuja. Ambos son previsibles.|n• Un Berserker múrloc golpea a todo el grupo cada 3 segundos hasta que muere — un múrloc que se escapa es donde se cae la sanación.",
	RAID_BOSS_NYMRISSA_DPS = "• Siempre primero los múrlocs: mátalos o ralentízalos antes de la burbuja; aturdimientos, raíces y empujones funcionan. Un Berserker muere al instante.|n• Mítico: primero el Frostscale — hace que los múrlocs a su alrededor reciban un 99 % menos de daño.|n• Luego de vuelta al jefe.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker: el Empowered Mindbreaker de Daggerspine Point fase 2, Beast From the Deep. Una criatura de las profundidades que Lady Selen'vjar sobrecarga con magia del Vacío robada.|n• El informe de un jugador en Wowhead: el rayo que te lanza es letal. Pasa una y otra vez por los orbes de sanación, y ten siempre claro dónde está el siguiente.|n• Es todo lo que tenemos. Ninguna fuente lista aún sus habilidades. Hasta entonces, la regla general: interrumpe lo que puedas y sal de los efectos de suelo.|n• Si te enfrentas a él, cuéntanos en Discord qué hizo y lo añadimos.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar: líder naga y jefa final de Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Fases: 1) Ritual Roles: sus capitanes protegen el ritual y drenan esencia del Vacío. 2) Beast From the Deep: potencia a un Mindbreaker. 3) Summoner's Fall: se enfrenta a ti ella misma.|n• Ninguna fuente describe aún sus habilidades: ni Wowhead, ni una guía, ni un post de foro. Eso sí, los jugadores en Wowhead dicen que es mucho más fácil que Faithbreaker Ger'lok.|n• Si te enfrentas a ella, cuéntanos en Discord qué hizo y lo añadimos.",
	RITUAL_ALERT_BINDING_NEBULA = "¡Binding Nebula! -> destruye la nebulosa",
	RITUAL_ALERT_SHADOWBOLT = "¡Interrumpe Shadowbolt Volley!",
	RITUAL_ALERT_DISSONANT = "¡Interrumpe Dissonant Reflections!",

	-- Challenges ----------------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• Aparecen tendrils que agarran, con un círculo verde giratorio — sal de él o quedarás inmovilizado y recibirás daño.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Saquea un Ritual Chest al final de cualquier sitio y entrega la misión \"Ritual Site Challenge Report: Tendrils\".",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Espíritus se manifiestan y lanzan hechizos — interrúmpelos o sufre su magia marchitadora.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Completa un sitio de Tier 3 y habla con Ranger Captain Lilatha en Lunargenta (el tier requerido baja cada semana).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Matar enemigos invoca refuerzos; cuanto más grande y fuerte sea el pull que matas, más fuertes los adds.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Completa un sitio de Tier 4 y habla con Lady Darkglen en Lunargenta (el tier requerido baja cada semana).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Los Dark Obelisks potencian a los enemigos cercanos — destruye los obeliscos para quitarles los buffs.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Completa un sitio de Tier 2 para una misión de Lady Darkglen y luego investiga 5 Dark Obelisks dentro de un sitio (el tier requerido baja cada semana).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Los enemigos muertos dejan un charco de magia del Vacío letal — sal de él.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Saquea un Tainted Bone Pile dentro de un sitio de Tier 2+ (mira las notas del sitio para la ubicación) y entrega la misión.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Hay enemigos extra repartidos por todo el sitio — espera grupos más densos.|n• Aumenta los Spoils mientras está activo (uno de los bonus más grandes).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Completa un sitio de Tier 2 y habla con Ranger Captain Lilatha en Lunargenta (el tier requerido baja cada semana).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Enemigos de élite patrullan el sitio — evita sus rutas cuando puedas.|n• Aumenta los Spoils mientras está activo.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procure\" tesoros únicos de un sitio de Tier 3+ (el tier requerido baja cada semana).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Enemigos aleatorios Y el jefe final están potenciados, marcados con un orbe flotante encima.|n• Aumenta los Spoils mientras está activo (uno de los bonus más grandes).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Saquea un Ember of Power dentro de un sitio de Tier 4 para iniciar la misión (el tier requerido baja cada semana).",
})

merge(ns._mhLocales and ns._mhLocales.ptBR, {
	-- Títulos de seção -------------------------------------------------------------
	RITUAL_COACH_SEC_OVERVIEW = "Visão geral",
