	-- Compartilhar (fase 3)
	RITUAL_COACH_SHARE_BTN = "Compartilhar dicas de challenges com o grupo",
	RITUAL_SHARE_CHALLENGES_HEADER = "Challenges de ritual por Spoils:",
	RITUAL_SHARE_XLOC_HEADER_FMT = "%s compartilhou dicas de challenges de ritual:",
	RITUAL_SHARE_CONFIRM_FMT = "Postar %d linhas de dicas de challenges no seu grupo?",
	RITUAL_SHARE_SENT_FMT = "%d linha(s) compartilhada(s) em %s.",
	RITUAL_SHARE_SENT_TEST_FMT = "%d linha(s) compartilhada(s) (modo de teste).",
	RITUAL_SHARE_NO_GROUP = "Entre em um grupo ou raide para compartilhar estas dicas (ou ative o modo de teste de compartilhamento).",
	RITUAL_SHARE_COMBAT = "Não é possível compartilhar em combate.",
	RITUAL_SHARE_COOLDOWN = "O compartilhamento está em recarga — tente de novo em instantes.",
	RITUAL_SHARE_BUSY = "Já há um compartilhamento em andamento.",
	RITUAL_SHARE_FAILED = "Não foi possível montar as dicas de challenges.",

	-- Dica semanal (por que a semanal de Ritual ainda está pendente)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Bloqueado: %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Bloqueado — desbloqueie os Ritual Sites pela linha de missões de introdução em Luaprata.",
	RITUAL_WEEKLY_HINT_PICKUP = "Ainda não pega — pegue a semanal desta semana no hub do Bazar em Luaprata.",
	RITUAL_WEEKLY_HINT_INTRO = "Este personagem ainda não terminou a linha de missões de introdução — comece \"Ranger Captain's Summons\" com Ranger Captain Lilatha em Luaprata (a etapa Void Strike acontece na zona de assalto ativa).",
	RITUAL_INTRO_STEP_FMT = "Linha de introdução neste personagem — etapa %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(já está no seu registro de missões)",
	RITUAL_INTRO_STEP_SUMMONS = "comece \"Ranger Captain's Summons\" com Ranger Captain Lilatha, no acampamento acima do Bazar.",
	RITUAL_INTRO_STEP_ALLIES = "faça \"Outfitting and Allies\" — conheça os aliados no acampamento de Lilatha.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — esta etapa acontece na zona de assalto ativa (veja Void Assaults abaixo).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — investigue os relatórios dos Sítios Rituais e depois interrompa um Sítio Ritual.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — apresente-se a Lady Darkglen no acampamento.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "Está no seu registro de missões — termine e entregue.",

	-- Intro / como funciona --------------------------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Escolhe o teu tier no Curious Obelisk; cada tier precisa ser limpo para desbloquear o próximo.|n• O obelisco diz o que cada tier pede: o Tier 3 exige 1 challenge ativo, o Tier 4 exige 2, o Tier 5 exige 4, o Tier 6 exige 6.|n• Tiers mais altos dão mais Spoils e renome. Item level recomendado, lido do próprio obelisco a 20 de agosto: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Passa o rato por um tier no menu para o confirmares — estes números mudam entre temporadas.",
	RITUAL_TIP_INTRO_SCORING = "• Spoils são sua pontuação; o Ritual Chest no final escala com eles.|n• Mortes: as 2 primeiras são de graça, depois cada morte corta 5% dos Spoils, até no máximo -50%.|n• Limpar com calma vale mais que pulls rápidos — morrer custa recompensa na hora.",
	RITUAL_TIP_INTRO_WEEKLY = "• A cada semana, o tier necessário para DESBLOQUEAR um challenge cai em um — com o tempo todo mundo desbloqueia tudo.|n• Não dá para desbloquear os 8 challenges em uma única semana.|n• Conta para a fileira de Mundo do Great Vault.|n• Reforços de renome: Ritual Tablet (primeiro local da semana), Ritual Tablet Fragment (segundo local) e Ritual Site Reports (escala com seus Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• Em combate, Regeneration Orbs aparecem e curam 15% da sua vida (renome 1).|n• Orb Potency (renome 4) aumenta essa cura.|n• Conte com os orbes em vez de gastar cooldowns com cura própria.",

	-- Daggerspine Point (Eversong Woods) ---------------------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, na costa oeste perto de Goldenmist Village.|n• Inimigos: nagas.|n• Ativo uma semana por vez; o obelisco mostra um ícone roxo no mapa.|n• Entre pelo Curious Obelisk e escolha lá seu tier + challenges.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Um cenário curto instanciado: cumpra objetivos e ondas de inimigos, depois um chefe final, e então saqueie o Ritual Chest.|n• Cenário visto no obelisco: \"A Strike From the Sea\" — a líder naga Selen'vjar (morte do chefe final ainda a confirmar).|n• Um local pode ter mais de um layout de cenário — a confirmar no jogo.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (desbloqueia o challenge Tainted Corpses): /way 66.09 62.58.|n• Dark Obelisks (missão Malevolent Boons — investigue 5 de 9): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• Pequenos tesouros e Regeneration Orbs estão espalhados pelo local.",

	-- Broken Throne (Zul'Aman) ----------------------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, no sul da zona.|n• Inimigos: cultistas da Twilight's Blade.|n• Ativo uma semana por vez; o obelisco mostra um ícone roxo no mapa.|n• Entre pelo Curious Obelisk e escolha lá seu tier + challenges.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Um cenário curto instanciado: cumpra objetivos e ondas de inimigos, depois um chefe final, e então saqueie o Ritual Chest.|n• Cenário visto no obelisco: \"A Corrupted Path\" — Faithbreaker Ger'lok corrompe tudo com o Vazio e é o chefe final.|n• MORTAL nos chefes finais (incluindo o Corrupted Amani Dragonhawk): reflexos do Vazio (Dissonant Reflections) surgem sem parar e conjuram Dissonant Realities — uma explosão enorme em tudo num raio de 100 metros. Não dá para fugir: INTERROMPA a conjuração e o reflexo some na hora. Guarde seu kick exatamente para isso.|n• Corrupted Amani Dragonhawk: uma Binding Nebula te PRENDE — você só sai quando MATA a própria nébula, então estoure-a assim que for capturado. Jogadores presos morrem para Volatile Plumage (a erupção de penas bate em centenas de milhares); nunca fique na frente do Shadowflame Breath.|n• Um local pode ter mais de um layout de cenário — a confirmar no jogo.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (desbloqueia o challenge Tainted Corpses): /way 47.91 36.52.|n• Dark Obelisks (missão Malevolent Boons — investigue 5 de 6): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54.|n• Destruir os Dark Obelisks remove os buffs que fortalecem os inimigos do local — eliminá-los deixa os chefes bem mais fáceis (só deixe-os de pé se estiver buscando a conquista sem obeliscos).|n• Pequenos tesouros e Regeneration Orbs estão espalhados pelo local.",
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291610} deixa pequenas POÇAS VERMELHAS. Fique numa delas para soakar: você toma só um dano pequeno. Uma poça em que ninguém fica explode com um dano enorme de Shadowflame e pode matar o grupo todo. Um jogador por poça basta.|n• {SPELL:1284125}: uma nébula se forma embaixo de um jogador aleatório. Ela causa dano a cada segundo e deixa você 40% mais lento. Você não consegue sair enquanto ela vive, então mate a nébula para se soltar.|n• {SPELL:1284081}: espelhos do Vazio surgem sem parar no meio e conjuram Dissonant Realities, um golpe enorme em todos num raio de 100 metros. Não dá para fugir dele. Interrompa a conjuração e o espelho some. Guarde seu kick para isso.|n• Fique ATRÁS do falcão-dragão. O Shadowflame Breath frontal dele é mortal.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Poças vermelhas: Fique numa poça vermelha para ela não explodir em todo mundo.|nEspelho: Interrompa a magia do espelho no meio, ou ele bate forte em todo mundo.|nNébula: Se uma nuvem escura prender você, mate a nuvem para sair.",
	RAID_BOSS_ROTMIRE_STEPS = "• Um chefe e um ciclo que se repete até ele morrer. Sede de Sangue no pull. Cada {SPELL:1221787} adiciona um acúmulo de Rotting Pustules que fica, então o dano no raide só aumenta: quanto mais longa a luta, mais difícil.|n• {SPELL:1221622}: círculos no chão mostram onde os adds surgem. Saia deles, ou você é arremessado para longe e toma muito dano. Cada add (Shroomling) persegue um jogador: leve-o para um único monte apertado perto do chefe, para o raide matar todos juntos.|n• Mate todos os adds antes de a barra de energia dele encher. Com 100 de energia ele lança {SPELL:1221637}: um golpe em todos, um empurrão e um DoT de 16 segundos. Um add que ainda estiver vivo ganha Fungal Frenzy: vida cheia, e não pode mais ser atordoado nem interrompido.|n• Depois de {SPELL:1221637}, cada corpo de add vira um Bursting Shroom. Mate todos em uns 16 segundos: cada um que sobrar explode no raide inteiro, e mais de uma explosão costuma dar wipe. É por isso que os adds morrem num único monte.|n• {SPELL:1222088} desacelera alguns jogadores e causa dano neles. Ande até a borda da sala antes de acabar: ele deixa uma área ({SPELL:1222129}) que fica. Mantenha livres o meio e o monte de adds, e saia de qualquer área.|n• No Heroico e no Mítico: também surge um add Sporecap que não se mexe. Interrompa o Poison Burst dele todas as vezes, ou o raide todo acumula um DoT. Leve os outros adds até ele e mate-os lá.|n• No Mítico: também vêm Funglings. Um corpo de Shroomling a menos de 10 metros de um corpo de Fungling cria um Bursting Doom Shroom, e isso dá wipe no raide. Mate os dois tipos em dois lugares separados.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Mate todos os adds do monte antes de a barra dele encher, e depois mate os cogumelos na hora.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "O dano aumenta a cada ciclo, então guarde cooldowns para o golpe forte quando a barra dele enche.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Troque com o outro tanque depois de cada soco forte, e deixe o chefe ao lado do monte de adds.",
	RAID_BOSS_ROTMIRE_QUICK = "Adds: Junte os pequenos adds de cogumelo num único monte e mate-os antes de a barra de energia dele encher.|nCogumelos: Quando a barra dele enche, os adds mortos viram cogumelos, então mate-os rápido antes que explodam.|nVinhas: Se vinhas deixarem você lento, ande até a borda da sala para a poça que elas deixam não atrapalhar ninguém.",
	RAID_BOSS_ROTMIRE_TANK = "• Troque com o outro tanque depois de cada {SPELL:1221781}: ele joga você para cima e faz você receber mais dano físico por 14 segundos (35% no Normal, 75% no Heroico e no Mítico). Use uma defesa para o golpe.|n• Mantenha o chefe ao lado do monte de adds, para o raide bater nele enquanto mata os adds. No Heroico e no Mítico: leve-o até o Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• O dano no raide sobe durante a luta toda: cada {SPELL:1221787} adiciona um acúmulo de Rotting Pustules, então cada ciclo é mais difícil que o anterior.|n• Planeje cooldowns de raide para {SPELL:1221637} (um golpe mais um DoT de 16 segundos em todos) e para qualquer Bursting Shroom que explodir.|n• O tanque atingido por {SPELL:1221781} recebe muito mais dano físico por 14 segundos.",
	RAID_BOSS_ROTMIRE_DPS = "• Faça cleave nos adds no monte deles, e deixe todos mortos antes de {SPELL:1221637}. Depois troque na hora para os Bursting Shrooms.|n• No Heroico e no Mítico: interrompa o Poison Burst do Sporecap todas as vezes.|n• No Mítico: Shroomlings e Funglings morrem em dois lugares separados, a pelo menos 10 metros um do outro.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100A entrada fica EMBAIXO D’ÁGUA|r — uma caverna submersa, então sua barra de fôlego corre antes da luta. Há bolhas de ar na entrada para recarregá-la.|n• Um chefe, um ciclo que se repete até ela morrer. Conta para a linha de Raid do seu Great Vault.|n• |cffffd100Os murlocs são a luta.|r {SPELL:1257717} coloca uma grande bolha no centro e os murlocs correm até ela. Mate ou desacelere-os ANTES que cheguem — cada um que entra vira um Berserker que atinge o grupo todo a cada 3 segundos. Leve o chefe até o maior grupo; os de longo alcance cuidam dos isolados.|n• Redemoinhos cercam a sala com uma única brecha — fiquem todos nessa brecha.|n• Quando um redemoinho chega à bolha, ela estoura: dano em todos e um empurrão. Posicione-se para não ser jogado na água — há tubarões.|n• {SPELL:1313393}: se atingir você, você deixa orbes de gelo por onde anda. Deixe-os juntos, longe da bolha e dos caminhos. No Normal não toque neles (dano acumulado e gelo escorregadio); no Heroico e no Mítico eles precisam ser pegos, senão estouram no grupo todo.|n• {SPELL:1260837} são quatro segundos de dano em todos — um cooldown de cura. No Heroico e no Mítico cada um a deixa bater mais forte: o enrage lento.|n• Aos 10 minutos vem o enrage final: fim do pull.|n• Sede de Sangue no pull.|n• Com base nos guias ao vivo e no módulo atual do DBM, ainda não testado por nós — conte o que você viu.",
	RAID_BOSS_NYMRISSA_TANK = "• Normal e Heroico: {SPELL:1282937} são vários segundos de golpes pesados em você — use uma defesa. Nada para mirar.|n• Mítico: {SPELL:1268562} é uma linha que empurra você e acumula; aponte-a para longe do grupo (pelas placas de gelo, ela as remove) e troque com o outro tanque nos acúmulos.|n• Mantenha-a junto ao maior grupo de murlocs, nunca em cima da bolha.",
	RAID_BOSS_NYMRISSA_HEALER = "• Planeje cooldowns para {SPELL:1260837} (quatro segundos em todos) e para o estouro da bolha. Os dois são previsíveis.|n• Um Berserker murloc atinge o grupo todo a cada 3 segundos até morrer — um murloc perdido é onde a cura desmorona.",
	RAID_BOSS_NYMRISSA_DPS = "• Sempre os murlocs primeiro: mate ou desacelere-os antes da bolha; atordoamentos, enraizamentos e empurrões funcionam. Um Berserker morre na hora.|n• Mítico: primeiro o Frostscale — ele faz os murlocs ao redor receberem 99% menos dano.|n• Depois de volta ao chefe.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker: o Empowered Mindbreaker de Daggerspine Point fase 2, Beast From the Deep. Uma criatura das profundezas que Lady Selen'vjar sobrecarrega com magia do Vazio roubada.|n• O relato de um jogador no Wowhead: o raio que ele atira em você é mortal. Passe sempre pelos orbes de cura, e saiba sempre onde está o próximo.|n• É tudo o que temos. Nenhuma fonte lista as habilidades dele ainda. Até lá, a regra geral: interrompa o que puder e saia dos efeitos no chão.|n• Se você enfrentá-lo, conte no Discord o que ele fez e entra aqui.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar: líder naga e chefe final de Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Fases: 1) Ritual Roles: os capitães dela guardam o ritual e drenam essência do Vazio. 2) Beast From the Deep: ela fortalece um Mindbreaker. 3) Summoner's Fall: ela enfrenta você pessoalmente.|n• Nenhuma fonte descreve as habilidades dela ainda: nem o Wowhead, nem um guia, nem um post de fórum. Mesmo assim, jogadores no Wowhead dizem que ela é bem mais fácil que Faithbreaker Ger'lok.|n• Se você enfrentá-la, conte no Discord o que ela fez e entra aqui.",
	RITUAL_ALERT_BINDING_NEBULA = "Binding Nebula! -> destrua a nébula",
	RITUAL_ALERT_SHADOWBOLT = "Interrompa Shadowbolt Volley!",
	RITUAL_ALERT_DISSONANT = "Interrompa Dissonant Reflections!",
	RITUAL_BOSS_GERLOK_STEPS = "• Ele invoca lacaios que o deixam (quase) imune a dano. Queime cada add assim que surgir. Os adds avançam com um canal de fogo que quase mata de uma vez, então saia dele.|n• {SPELL:1273031} é A conjuração para interromper: um golpe forte em todos por perto. Nem toda conjuração dele pode ser interrompida, então guarde seu kick para ela.|n• {SPELL:1279186} é spammado. Quebre a linha de visão atrás dos pilares.|n• Mantenha-o NA plataforma dele. Puxá-lo para baixo ou para fora dela reseta a luta (Rob, no jogo). O espaço é apertado, mas não procure espaço mais abaixo.|n• Challenge Embers: cada Ember que continua acesa deixa ele muito mais forte. Um jogador no Wowhead viu uns 60% a mais de vida e dano com as quatro ativas. Mate os monstros marcados em volta de cada Ember antes do chefe para apagá-la.",
	RITUAL_BOSS_GERLOK_QUICK = "Adds: Mate os ajudantes dele na hora, porque enquanto eles vivem ele quase não toma dano.|nInterromper: Guarde sua interrupção para Shadowbolt Volley, o golpe forte dele em todos.|nPilares: Esconda-se atrás de um pilar para o Shadow Blast dele não acertar você.",

	-- Challenges ------------------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• Tendrils que agarram surgem com um círculo verde girando — saia dele ou você fica enraizado e toma dano.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Saqueie um Ritual Chest no final de qualquer local e entregue a missão \"Ritual Site Challenge Report: Tendrils\".",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Espíritos se manifestam e conjuram feitiços — interrompa-os ou sofra magia debilitante.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Limpe um local de Tier 3 e fale com Ranger Captain Lilatha em Luaprata (o tier exigido cai a cada semana).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Abates invocam reforços; quanto maior e mais forte o pull que você mata, mais fortes os adds.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Limpe um local de Tier 4 e fale com Lady Darkglen em Luaprata (o tier exigido cai a cada semana).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Dark Obelisks fortalecem inimigos próximos — destrua os obeliscos para remover os buffs.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Limpe um local de Tier 2 para uma missão de Lady Darkglen e depois investigue 5 Dark Obelisks dentro de um local (o tier exigido cai a cada semana).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Inimigos mortos deixam uma poça de magia do Vazio letal — saia dela.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Saqueie um Tainted Bone Pile dentro de um local de Tier 2+ (veja as notas do local para a localização) e entregue a missão.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Inimigos extras espalhados por todo o local — espere packs mais densos.|n• Aumenta os Spoils enquanto ativo (um dos bônus maiores).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Limpe um local de Tier 2 e fale com Ranger Captain Lilatha em Luaprata (o tier exigido cai a cada semana).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Inimigos de elite patrulham o local — evite as rotas deles quando puder.|n• Aumenta os Spoils enquanto ativo.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procure\" tesouros únicos de um local de Tier 3+ (o tier exigido cai a cada semana).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Inimigos aleatórios E o chefe final ficam fortalecidos, marcados por um orbe flutuante acima deles.|n• Aumenta os Spoils enquanto ativo (um dos bônus maiores).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Saqueie um Ember of Power dentro de um local de Tier 4 para iniciar a missão (o tier exigido cai a cada semana).",
})
